exercises.solution:
// W zwyklym, "nie-modulowym" skrypcie, zmienne zadeklarowane na najwyzszym
// poziomie moga byc (w zaleznosci od kontekstu) globalnie dostepne dla
// innych skryptow na tej samej stronie.
//
// Modul ES ma WLASNY, ODIZOLOWANY zasieg - zmienne zadeklarowane w module
// sa domyslnie NIEDOSTEPNE dla innych plikow, chyba ze zostana jawnie
// oznaczone slowem kluczowym export. Tylko WYEKSPORTOWANE wartosci moga
// zostac zaimportowane i uzyte w innym module.

// mathUtils.js
export const PI = 3.14159;
export function dodaj(a, b) {
  return a + b;
}

// inny-plik.js
import { PI, dodaj } from "./mathUtils.js";
console.log(dodaj(2, 3)); // 5
console.log(PI); // 3.14159

// stringUtils.js
export function capitalize(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// inny-plik.js
import { capitalize } from "./stringUtils.js";
console.log(capitalize("react")); // "React"

// Natywne moduly ES (uruchamiane bezposrednio przez Node.js lub
// przegladarke, bez posrednika) wymagaja PELNEJ, jednoznacznej sciezki
// do pliku, wlacznie z rozszerzeniem - silnik JavaScript nie "zgaduje"
// rozszerzenia pliku.
//
// Bundlery (jak Vite, uzywany w projektach React) dodaja WLASNA warstwe
// rozwiazywania sciezek ("module resolution") - automatycznie probuja
// rozne rozszerzenia (.js, .jsx, .ts) za programiste, dzieki czemu
// rozszerzenie mozna czesto pominac dla wygody.

// konfiguracja.js
export const USTAWIENIA = { jezyk: "pl", motyw: "jasny" };

// inny-plik.js
import { USTAWIENIA } from "./konfiguracja.js";
console.log(USTAWIENIA.jezyk); // "pl"

// Dzielenie kodu na wiele modulow jest lepsza praktyka, poniewaz:
// 1. Kazdy modul ma JASNA, POJEDYNCZA odpowiedzialnosc (np. mathUtils.js
//    zajmuje sie WYLACZNIE matematyka, stringUtils.js WYLACZNIE stringami)
//    - latwiej znalezc i zrozumiec konkretny fragment kodu.
// 2. Latwiejsze UTRZYMANIE - zmiana logiki matematycznej nie wymaga
//    przegladania kodu operujacego na stringach.
// 3. Latwiejsze TESTOWANIE - kazdy modul mozna testowac niezaleznie.
// 4. PONOWNE UZYCIE - jeden modul moze byc importowany w wielu roznych
//    miejscach projektu, bez kopiowania-wklejania tego samego kodu.

// React opiera sie na DOKLADNIE tym samym mechanizmie modulow ES, ktorego
// wlasnie sie uczysz - kazdy komponent to po prostu MODUL:
//
// Button.jsx
// export default function Button() { ... }
//
// App.jsx
// import Button from "./Button.jsx";
//
// Skladnia jest IDENTYCZNA jak przy imporcie funkcji matematycznych z
// mathUtils.js - jedyna roznica jest KONCEPCYJNA: zamiast importowac
// funkcje pomocnicze, importujesz komponenty UI, ktore mozna umiescic
// w drzewie interfejsu aplikacji.

// stale.js
export const nazwaAplikacji = "javaQuest";

// main.js
import { nazwaAplikacji } from "./stale.js";
console.log(nazwaAplikacji); // -> javaQuest

// licznik.js
let prywatna = 42;
export function pobierz() {
  return prywatna;
}

// main.js
import { pobierz } from "./licznik.js";
console.log(pobierz());          // -> 42
console.log(typeof prywatna);    // -> undefined (zmienna zostala w module)

// a.js
console.log("a ladowany");
export const wartosc = 1;

// b.js
import { wartosc } from "./a.js";
export const b = wartosc + 1;

// c.js
import { wartosc } from "./a.js";
export const c = wartosc + 2;

// main.js
import { b } from "./b.js";
import { c } from "./c.js";
console.log(b, c);
// a ladowany (tylko raz), potem 2 3

// a.js
console.log("a");

// b.js
console.log("b");

// main.js
import "./a.js";
import "./b.js";
console.log("main");
// kolejnosc: a, b, main

// pomocnik.js
console.log("pomocnik ladowany");
export const x = 1;

// main.js
console.log("main startuje");
import { x } from "./pomocnik.js";
console.log(x);
// pomocnik ladowany, main startuje, 1

// main.js
var globalna = 1;

console.log(typeof globalThis.globalna); // -> undefined
console.log(this);                       // -> undefined

// main.js
try {
  niezadeklarowana = 5;
} catch (error) {
  console.log(error.name); // -> ReferenceError
}

// dane.js
export let liczba = 1;

// main.js
import { liczba } from "./dane.js";

try {
  liczba = 2;
} catch (error) {
  console.log(error.name); // -> TypeError
}
console.log(liczba);       // -> 1

// licznik.js
export let licznik = 0;
export function zwieksz() {
  licznik++;
}

// main.js
import { licznik, zwieksz } from "./licznik.js";

console.log(licznik); // -> 0
zwieksz();
console.log(licznik); // -> 1 (zywe wiazanie)

// uzytkownicy.js
const lista = [];
export function dodaj(imie) {
  lista.push(imie);
}
export function ile() {
  return lista.length;
}

// main.js
import { dodaj, ile } from "./uzytkownicy.js";
dodaj("Ala");
dodaj("Jan");
console.log(ile()); // -> 2

// konfig.js
export const ustawienia = { motyw: "jasny" };

// a.js
import { ustawienia } from "./konfig.js";
ustawienia.motyw = "ciemny";

// main.js
import { ustawienia } from "./konfig.js";
import "./a.js";
console.log(ustawienia.motyw); // -> ciemny

// narzedzia.js
function podwoj(x) { return x * 2; }
function potroj(x) { return x * 3; }

export { podwoj, potroj };

// main.js
import { podwoj, potroj } from "./narzedzia.js";
console.log(podwoj(5), potroj(5)); // -> 10 15

// tekst.js
export function powitaj(imie) {
  return "Czesc, " + imie;
}

// main.js
import { powitaj as przywitaj } from "./tekst.js";
console.log(przywitaj("Ola")); // -> Czesc, Ola

// main.js
console.log(typeof require);
console.log(typeof module);
console.log(typeof exports);
// undefined undefined undefined

// klasa.js
export class Punkt {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
  opis() {
    return "(" + this.x + ", " + this.y + ")";
  }
}

// main.js
import { Punkt } from "./klasa.js";
console.log(new Punkt(1, 2).opis()); // -> (1, 2)

// main.js
console.log(import.meta.url.includes("main.js")); // -> true
// import.meta zawiera metadane biezacego modulu (np. jego adres url).

// id.js
let ostatnie = 0;
export function kolejneId() {
  ostatnie++;
  return ostatnie;
}

// main.js
import { kolejneId } from "./id.js";
console.log(kolejneId(), kolejneId(), kolejneId()); // -> 1 2 3

// a.js
const prywatna = 1;
export const publiczna = 2;

// main.js
import { publiczna } from "./a.js";
// import { prywatna } from "./a.js"; // -> SyntaxError: modul a.js nie eksportuje "prywatna"
console.log(publiczna);

// a.js
export const start = 1;

// b.js
export const zwieksz = x => x + 1;

// c.js
export const razy10 = x => x * 10;

// main.js
import { start } from "./a.js";
import { zwieksz } from "./b.js";
import { razy10 } from "./c.js";
console.log(razy10(zwieksz(start))); // -> 20

// inicjalizacja.js
console.log("modul zaladowany");

// main.js
import "./inicjalizacja.js";
console.log("dalej");
// przydatne np. do rejestracji globalnych ustawien albo wypelnienia (polyfill)

// matematyka.js
export const dodaj = (a, b) => a + b;
export const odejmij = (a, b) => a - b;
export const pomnoz = (a, b) => a * b;

// main.js
import { dodaj, odejmij, pomnoz } from "./matematyka.js";
console.log(dodaj(6, 3), odejmij(6, 3), pomnoz(6, 3)); // -> 9 3 18

// stan.js
export let stan = "start";
export function ustaw(v) {
  stan = v;
}

// main.js
import { stan, ustaw } from "./stan.js";
console.log(stan);   // -> start
ustaw("koniec");
console.log(stan);   // -> koniec
// stan = "x" w main.js byloby bledem - importowane wiazanie jest tylko do odczytu.

// main.js
var lokalna = 1;
console.log(typeof globalThis.lokalna); // wlasny zasieg: undefined
console.log(this);                       // tryb strict / modul: undefined
console.log(typeof require);             // brak require: undefined
console.log(import.meta.url.length > 0); // metadane modulu: true

